def semver_sort(versions):
    def parse(v):
        main = v.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is None:
            has_pre = 0
            pre_key = ()
        else:
            has_pre = 1
            idents = pre.split('.')
            pre_key = tuple(
                (0, int(ident)) if ident.isdigit() else (1, ident)
                for ident in idents
            )
        # release (no prerelease) should sort after prerelease versions
        # use flag: 0 if has prerelease, 1 if not
        no_pre_flag = 0 if has_pre else 1
        return (major, minor, patch, no_pre_flag, pre_key)

    return sorted(versions, key=parse)

